def solve(s=None):
    if s is None:
        import sys
        s = sys.stdin.read()
        if s is None:
            s = ''
        s = s.strip()
    # stack for opening brackets
    stack = []
    pairs = {')':'(', ']':'[', '}':'{'}
    opens = set(pairs.values())
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        else:
            # ignore other characters
            continue
    return not stack

def solve(s: str) -> int:
    """Convert a Roman numeral to an integer.
    Supports standard symbols I, V, X, L, C, D, M with subtractive notation.
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        if i + 1 < n and values[s[i]] < values[s[i + 1]]:
            total += values[s[i + 1]] - values[s[i]]
            i += 2
        else:
            total += values[s[i]]
            i += 1
    return total

