def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer or one of '+', '-', '*', '/'.
    Division truncates toward zero as specified.
    """
    stack = []
    for t in tokens:
        if t not in {"+", "-", "*", "/"}:
            stack.append(int(t))
        else:
            b = stack.pop()
            a = stack.pop()
            if t == "+":
                stack.append(a + b)
            elif t == "-":
                stack.append(a - b)
            elif t == "*":
                stack.append(a * b)
            else:  # division
                # Truncate toward zero.
                # Using int(a / b) works because Python's '/' returns float, int() truncates toward zero.
                stack.append(int(a / b))
    return stack[0] if stack else 0

