def solve(s):
    """Run-length encode the input.
    Accepts a string or any iterable of characters.
    Returns a list of [character, count] pairs.
    """
    # If it's not a string, try to treat it as an iterable of characters
    if not isinstance(s, str):
        try:
            s = ''.join(s)
        except Exception:
            raise TypeError('Input must be a string or iterable of characters')
    if not s:
        return []
    res = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

