    m=len(grid); n=len(grid[0]) if m else 0
    visited=[[False]*n for _ in range(m)]
    def dfs(i,j):
        stack=[(i,j)]
        while stack:
            x,y=stack.pop()
            if visited[x][y]:
                continue
            visited[x][y]=True
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx,ny=x+dx,y+dy
                if 0<=nx<m and 0<=ny<n and not visited[nx][ny] and grid[nx][ny]==1:
                    stack.append((nx,ny))
    count=0
    for i in range(m):
        for j in range(n):
            if grid[i][j]==1 and not visited[i][j]:
                dfs(i,j)
                count+=1
    return count

