def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings of integers or '+', '-', '*', '/'. Division truncates toward zero.
    Returns integer result.
    """
    stack = []
    for tok in tokens:
        if tok not in {"+", "-", "*", "/"}:
            stack.append(int(tok))
        else:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                stack.append(int(a / b))
    return stack[0] if stack else 0

